sed 's#^toTitle();$#toTitle();window.__t={startGame,CLASSES,T,TP,tileUnder,get P(){return P},get en(){return enemies},get gems(){return gems},keys,update,render,get st(){return state},get time(){return time},setTime:v=>{time=v},get SI(){return SI},get kills(){return kills},choose,get opts(){return lvOpts},nextStage,setDI:i=>{DI=i},get disc(){return discovered.size},openLevel,addLv:n=>{pendingLv+=n},pause,openCodex,setTab:t=>{codexTab=t},renderCodex,go:i=>{SI=i;enterStage()},stageClear};#' ../index.html > game.html
